CREATE TABLE ACCOUNT (acct_id NUMERIC(11) PRIMARY KEY, active_status VARCHAR(1), curr_bal NUMERIC(12,2), credit_limit NUMERIC(12,2), cash_credit_limit NUMERIC(12,2), open_date VARCHAR(10), expiration_date VARCHAR(10), reissue_date VARCHAR(10), curr_cyc_credit NUMERIC(12,2), curr_cyc_debit NUMERIC(12,2), addr_zip VARCHAR(10), group_id VARCHAR(10));
CREATE TABLE CUSTOMER (cust_id NUMERIC(9) PRIMARY KEY, first_name VARCHAR(25), middle_name VARCHAR(25), last_name VARCHAR(25), addr_line_1 VARCHAR(50), addr_line_2 VARCHAR(50), addr_line_3 VARCHAR(50), addr_state_cd VARCHAR(2), addr_country_cd VARCHAR(3), addr_zip VARCHAR(10), phone_num_1 VARCHAR(15), phone_num_2 VARCHAR(15), ssn VARCHAR(9), govt_issued_id VARCHAR(20), dob VARCHAR(10), eft_account_id VARCHAR(10), primary_card_holder_ind VARCHAR(1), fico_credit_score INTEGER);
CREATE TABLE CARD (card_num VARCHAR(16) PRIMARY KEY, acct_id NUMERIC(11) NOT NULL, cvv_cd INTEGER, embossed_name VARCHAR(50), expiration_date VARCHAR(10), active_status VARCHAR(1), CONSTRAINT fk_card_account FOREIGN KEY (acct_id) REFERENCES ACCOUNT(acct_id));
CREATE TABLE CARD_XREF (card_num VARCHAR(16) PRIMARY KEY, cust_id NUMERIC(9) NOT NULL, acct_id NUMERIC(11) NOT NULL, CONSTRAINT fk_xref_customer FOREIGN KEY (cust_id) REFERENCES CUSTOMER(cust_id), CONSTRAINT fk_xref_account FOREIGN KEY (acct_id) REFERENCES ACCOUNT(acct_id));
CREATE TABLE TRAN_TYPE (tran_type VARCHAR(2) PRIMARY KEY, tran_type_desc VARCHAR(50));
CREATE TABLE TRAN_CATEGORY (tran_type_cd VARCHAR(2), tran_cat_cd INTEGER, tran_cat_type_desc VARCHAR(50), PRIMARY KEY (tran_type_cd, tran_cat_cd), CONSTRAINT fk_category_type FOREIGN KEY (tran_type_cd) REFERENCES TRAN_TYPE(tran_type));
CREATE TABLE "transaction" (tran_id VARCHAR(16) PRIMARY KEY, tran_type_cd VARCHAR(2), tran_cat_cd INTEGER, tran_source VARCHAR(10), tran_desc VARCHAR(100), tran_amt NUMERIC(11,2), merchant_id NUMERIC(9), merchant_name VARCHAR(50), merchant_city VARCHAR(50), merchant_zip VARCHAR(10), card_num VARCHAR(16) NOT NULL, acct_id NUMERIC(11) NOT NULL, orig_ts VARCHAR(26), proc_ts VARCHAR(26), CONSTRAINT fk_transaction_card FOREIGN KEY (card_num) REFERENCES CARD(card_num), CONSTRAINT fk_transaction_account FOREIGN KEY (acct_id) REFERENCES ACCOUNT(acct_id));
CREATE TABLE USER_SECURITY (sec_usr_id VARCHAR(8) PRIMARY KEY, fname VARCHAR(20), lname VARCHAR(20), pwd VARCHAR(8), type VARCHAR(1));
CREATE TABLE TRAN_CAT_BAL (acct_id NUMERIC(11), type_cd VARCHAR(2), cat_cd INTEGER, balance NUMERIC(11,2), PRIMARY KEY (acct_id, type_cd, cat_cd), CONSTRAINT fk_bal_account FOREIGN KEY (acct_id) REFERENCES ACCOUNT(acct_id), CONSTRAINT fk_bal_type FOREIGN KEY (type_cd) REFERENCES TRAN_TYPE(tran_type), CONSTRAINT fk_bal_category FOREIGN KEY (type_cd, cat_cd) REFERENCES TRAN_CATEGORY(tran_type_cd, tran_cat_cd));
